/**
 * Validate the request before anything is sent.
 *
 * The batch id ends up in a SQL statement, so it is checked against the UUID
 * format here.  A value that is not a UUID never reaches the database.
 */

const items = $input.all();
const payload = (items[0] && items[0].json) || {};
const body = payload.body && typeof payload.body === 'object' ? payload.body : payload;

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const batchId = String(body.batch_id || body.batchId || '').trim().toLowerCase();
if (!UUID.test(batchId)) {
  throw new Error('invalid_batch_id: the request must carry a batch id in UUID format');
}

const limit = Number(body.limit || 0);
return [{
  json: {
    batch_id: batchId,
    limit: Number.isFinite(limit) && limit > 0 ? Math.floor(limit) : 0,
    requested_at: new Date().toISOString(),
  },
}];
